import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./AdminPage.css";

function AdminPage() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("dashboard");
  const [slots, setSlots] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [loadingSlots, setLoadingSlots] = useState(true);
  const [loadingBookings, setLoadingBookings] = useState(true);
  const [errorSlots, setErrorSlots] = useState(null);
  const [errorBookings, setErrorBookings] = useState(null);

  useEffect(() => {
    // Fetch slots with explicit pagination params
    fetch(
      "http://localhost:8081/api/slots?page=0&size=10&sortBy=slotId&direction=asc"
    )
      .then((res) => {
        if (!res.ok) throw new Error(`Slots API error: ${res.status}`);
        return res.json();
      })
      .then((data) => {
        console.log("Slots API response:", data);
        if (data && Array.isArray(data.content)) {
          setSlots(data.content);
        } else {
          console.warn("Slots data.content missing or not an array");
          setSlots([]);
        }
        setLoadingSlots(false);
      })
      .catch((err) => {
        console.error("Error fetching slots:", err);
        setErrorSlots(err.message);
        setLoadingSlots(false);
      });

    // Fetch bookings (assuming it's a plain array)
    fetch("http://localhost:8081/api/bookings")
      .then((res) => {
        if (!res.ok) throw new Error(`Bookings API error: ${res.status}`);
        return res.json();
      })
      .then((data) => {
        console.log("Bookings API response:", data);
        setBookings(data);
        setLoadingBookings(false);
      })
      .catch((err) => {
        console.error("Error fetching bookings:", err);
        setErrorBookings(err.message);
        setLoadingBookings(false);
      });
  }, []);

  const handleLogout = () => {
    localStorage.clear();
    navigate("/admin-login");
  };

  const renderContent = () => {
    if (activeTab === "dashboard") {
      return (
        <div className="dashboard-content">
          <div className="stat-card">
            <h3>Total Slots</h3>
            <p>{slots.length}</p>
          </div>
          <div className="stat-card">
            <h3>Available Slots</h3>
            <p>{slots.filter((s) => s.isAvailable).length}</p>
          </div>
          <div className="stat-card">
            <h3>Total Bookings</h3>
            <p>{bookings.length}</p>
          </div>
        </div>
      );
    }

    if (activeTab === "bookings") {
      if (loadingBookings) return <p>Loading bookings...</p>;
      if (errorBookings) return <p>Error loading bookings: {errorBookings}</p>;
      if (!bookings.length) return <p>No bookings found.</p>;

      return (
        <div>
          <h2>All Bookings</h2>
          <table>
            <thead>
              <tr>
                <th>Booking ID</th>
                <th>Vehicle</th>
                <th>Start</th>
                <th>End</th>
                <th>Cost</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map((b) => (
                <tr key={b.bookingId || b.id}>
                  <td>{b.bookingId || b.id}</td>
                  <td>{b.vehicleNumber}</td>
                  <td>{new Date(b.startTime).toLocaleString()}</td>
                  <td>{new Date(b.endTime).toLocaleString()}</td>
                  <td>${b.totalCost}</td>
                  <td>{b.status}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
    }

    if (activeTab === "slots") {
      if (loadingSlots) return <p>Loading slots...</p>;
      if (errorSlots) return <p>Error loading slots: {errorSlots}</p>;
      if (!slots.length) return <p>No slots found.</p>;

      return (
        <div>
          <h2>Manage Slots</h2>
          <table>
            <thead>
              <tr>
                <th>Slot ID</th>
                <th>Number</th>
                <th>Type</th>
                <th>Rate</th>
                <th>Available</th>
                <th>Location</th>
                <th>Floor</th>
                <th>Section</th>
              </tr>
            </thead>
            <tbody>
              {slots.map((s) => (
                <tr key={s.slotId}>
                  <td>{s.slotId}</td>
                  <td>{s.slotNumber}</td>
                  <td>{s.slotType}</td>
                  <td>${s.hourlyRate}</td>
                  <td>{s.isAvailable ? "Yes" : "No"}</td>
                  <td>{s.location}</td>
                  <td>{s.floor}</td>
                  <td>{s.section}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
    }
  };

  return (
    <div className="admin-dashboard">
      <div className="sidebar">
        <h2>Admin Panel</h2>
        <ul>
          <li
            className={activeTab === "dashboard" ? "active" : ""}
            onClick={() => setActiveTab("dashboard")}
          >
            Dashboard
          </li>
          <li
            className={activeTab === "bookings" ? "active" : ""}
            onClick={() => setActiveTab("bookings")}
          >
            View Bookings
          </li>
          <li
            className={activeTab === "slots" ? "active" : ""}
            onClick={() => setActiveTab("slots")}
          >
            Manage Slots
          </li>
        </ul>
      </div>

      <div className="main-content">
        <div className="topbar">
          <h1>{activeTab.charAt(0).toUpperCase() + activeTab.slice(1)}</h1>
          <button onClick={handleLogout}>Logout</button>
        </div>
        <div className="content-area">{renderContent()}</div>
      </div>
    </div>
  );
}

export default AdminPage;
